####### # Setup #######
Context('Numeric'); $little = random(2,10,2); $medium = $little+1; $medium2 = $medium+1; do {$big = random($medium2,15,1);} until ($big % $little != 0); $steepest = Formula("$big/$little"); $shallowest = Formula("$little/$big");
###### # Body ######
BEGIN_PGML Fill in the variables [`A\text{,}`] [`B\text{,}`] and [`C`] in [`Ax + By = C`] with the numbers [`[$little], [$medium]`] and [`[$big]\text{.}`] You may only use each number once in each part.
END_PGML
########## # Scaffold ##########
Scaffold::Begin(numbered => 1,is_open => "correct_or_first_incorrect",can_open => always,);
######### # Section #########
Section::Begin("");
BEGIN_PGML For the steepest possible slope, [`A`] must be [_]{$big}{4}, [`B`] must be [_]{$little}{4}, and [`C`] must be [_]{$medium}{4}.
END_PGML
########## # Solution ##########
BEGIN_PGML_SOLUTION Let's put [`Ax + By = C`] into slope-intercept form. Then, the equation becomes [`y = \frac{-A}{B}x + \frac{C}{B}\text{.}`] To make the steepest slope possible, we must maximize the fraction [`\frac{A}{B}\text{.}`] The possibilities are [`\frac{[$little]}{[$medium]}\text{,}`] [`\frac{[$little]}{[$big]}\text{,}`] [`\frac{[$medium]}{[$little]}\text{,}`] [`\frac{[$medium]}{[$big]}\text{,}`] [`\frac{[$big]}{[$little]}\text{,}`] and [`\frac{[$big]}{[$medium]}\text{.}`] The biggest of these is [`\frac{[$big]}{[$little]}\text{.}`] Thus, [`A`] must equal [$big], [`B`] must equal [$little], and [`C`] must equal [$medium].
END_PGML_SOLUTION
Section::End();
######### # Section #########
Section::Begin("");
BEGIN_PGML For the shallowest possible slope, [`A`] must be [_]{$little}{4}, [`B`] must be [_]{$big}{4}, and [`C`] must be [_]{$medium}{4}.
END_PGML
########## # Solution ##########
BEGIN_PGML_SOLUTION To make the shallowest slope possible, we must minimize the fraction [`\frac{A}{B}\text{.}`] The smallest of the possible fractions is [`\frac{[$little]}{[$big]}\text{.}`] Thus, [`A`] must equal [$little], [`B`] must equal [$big], and [`C`] must equal [$medium].
END_PGML_SOLUTION
